  _ = `De gyroscopische invoer is alleen actief wanneer de driehoekknop ingedrukt is.`,
  _ = `Activatieknop gyroscoop: linkerstick (klikken)`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de linkerstick indrukt.`,
  _ = `Activatieknop gyroscoop: rechterstick (klikken)`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de rechterstick indrukt.`,
  _ = `Activatieknop gyroscoop: Capture-knop (klikken)`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de Capture-knop indrukt.`,
  _ = `Activatieknop gyroscoop: rechtertrekker`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de rechtertrekker indrukt.`,
  _ = `Activatieknop gyroscoop: linkertrekker`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de linkertrekker indrukt.`,
  _ = `Activatieknop gyroscoop: linkerstick (aanraken)`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de linkerstick aanraakt.`,
