  _ = `Activatieknop gyroscoop: linkertrekker`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de linkertrekker indrukt.`,
  _ = `Activatieknop gyroscoop: linkerstick (aanraken)`,
  _ = `De gyroscopische invoer is alleen actief wanneer je de linkerstick aanraakt.`,
  _ = `Activatieknop gyroscoop: rechterstick (aanraken)`,
